import { useEffect, useState } from "react";
import {
  fetchLoggedUser,
  fetchUserRepos,
  fetchCommits,
  uploadFile
} from "./api/githubApi";
import { fetchPRHeatmap } from "./api/githubApi";
import { fetchMergeHeatmap } from "./api/githubApi";

import MonthYearPicker from "./components/MonthYearPicker";

function App() {
  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");
  const [liveCommits, setLiveCommits] = useState([]);
  const fetchLiveFeed = async () => {
  const payload = { owner, repo: selectedRepo };
  const res = await fetchLiveCommits(payload);
  setLiveCommits(res.data || []);
};

  const [commitHeatmap, setCommitHeatmap] = useState({});
  const [userCreatedAt, setUserCreatedAt] = useState(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadMessage, setUploadMessage] = useState("Upload via dashboard");

  const [actionType, setActionType] = useState("commits");

  const [darkMode, setDarkMode] = useState(true);

  const [prHeatmap, setPrHeatmap] = useState({});

  const [mergeHeatmap, setMergeHeatmap] = useState({});

  useEffect(() => {
  if (!owner || !selectedRepo) return;

  fetchLiveFeed();

  const interval = setInterval(() => {
    fetchLiveFeed();
  }, 10000); // every 10 seconds

  return () => clearInterval(interval);

}, [owner, selectedRepo]);

  // ✅ FULL SCREEN DARK MODE FIX
  useEffect(() => {
    document.body.style.margin = "0";
    document.body.style.backgroundColor = darkMode ? "#0F172A" : "#F8FAFC";
    document.body.style.color = darkMode ? "#F8FAFC" : "#0F172A";
  }, [darkMode]);

  // ✅ TOKEN
  useEffect(() => {
    const query = new URLSearchParams(window.location.search);
    const token = query.get("token");
    if (token) {
      localStorage.setItem("token", token);
      window.history.replaceState({}, document.title, "/");
    }
  }, []);

  // ✅ LOAD USER + REPOS
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    fetchLoggedUser().then(res => {
      setOwner(res.data.login);
      setUserCreatedAt(res.data.created_at);
    });

    fetchUserRepos().then(res => {
      setRepos(res.data);
      if (res.data.length > 0) setSelectedRepo(res.data[0].name);
    });
  }, []);

  const buildPRHeatmap = async (payload) => {
  const res = await fetchPRHeatmap(payload);
  setPrHeatmap(res.data);
  };

  const buildMergeHeatmap = async (payload) => {
  const res = await fetchMergeHeatmap(payload);
  setMergeHeatmap(res.data);
};

  // ✅ FETCH COMMIT HEATMAP
  const buildCommitHeatmap = async (payload) => {
    const commitRes = await fetchCommits(payload);

    const map = {};
    commitRes.data.forEach(commit => {
      const date = commit.commit.committer.date.substring(0, 10);
      map[date] = (map[date] || 0) + 1;
    });

    setCommitHeatmap(map);
  };

  // ✅ ANALYZE
  const fetchData = async () => {
  if (!owner || !selectedRepo) return alert("Missing owner or repo");

  const payload = { owner, repo: selectedRepo, startDate, endDate };

  if (actionType === "commits") {
    await buildCommitHeatmap(payload);
  }

  if (actionType === "prs") {
    await buildPRHeatmap(payload);
  }

  if (actionType === "merge") {
    await buildMergeHeatmap(payload);
  }

  if (actionType === "clone") {
    window.open(`https://github.com/${owner}/${selectedRepo}.git`, "_blank");
  }
};



  // ✅ UPLOAD FILE
  const handleUpload = async () => {
    if (!selectedFile) return alert("Select a file");

    const reader = new FileReader();
    reader.onload = async () => {
      const base64Content = reader.result.split(",")[1];

      await uploadFile({
        owner,
        repo: selectedRepo,
        path: "uploads/" + selectedFile.name,
        content: base64Content,
        message: uploadMessage
      });

      alert("✅ Uploaded to GitHub");
      await fetchData();
    };

    reader.readAsDataURL(selectedFile);
  };

  // ✅ RENDER HEATMAP GRID
  const renderHeatmap = () => {
  const data =
    actionType === "commits" ? commitHeatmap :
    actionType === "prs" ? prHeatmap :
    actionType === "merge" ? mergeHeatmap :
    {};

  const days = Object.keys(data).sort();

  return (
    <div className="heatmap-grid">
      {days.map(date => {
        const level = data[date] || 0;
        return (
          <div
            key={date}
            title={`${date} : ${level}`}
            className={`heat-box level-${Math.min(level, 4)}`}
          />
        );
      })}
    </div>
  );
};


  return (
    <div style={styles.container}>
      {/* ✅ TOP BAR */}
      <div style={styles.topBar}>
        <h2>GitHub Analytics</h2>
        <button onClick={() => setDarkMode(!darkMode)}>
          {darkMode ? "☀ Light" : "🌙 Dark"}
        </button>
      </div>

      {!owner && (
        <button onClick={() => window.location.href =
          "http://localhost:8080/auth/github"}>
          Login with GitHub
        </button>
      )}

      {owner && <h3>Logged in as: {owner}</h3>}

      {owner && (
        <>
          <div style={styles.form}>
            <select onChange={e => setSelectedRepo(e.target.value)}>
              {repos.map(repo => (
                <option key={repo.id} value={repo.name}>{repo.name}</option>
              ))}
            </select>

            <MonthYearPicker
              userCreatedAt={userCreatedAt}
              onChange={({ startDate, endDate }) => {
                setStartDate(startDate);
                setEndDate(endDate);
              }}
            />

            <select onChange={(e) => setActionType(e.target.value)}>
              <option value="commits">Commits</option>
              <option value="prs">Pull Requests</option>
              <option value="merge">Merged PRs</option>
              <option value="clone">Clone Repo</option>
            </select>



            <button onClick={fetchData}>Analyze</button>
          </div>

          {/* ✅ HEATMAP */}
          <div style={styles.heatmapBox}>
            <div style={styles.topRightUpload}>
              <input type="file" onChange={e => setSelectedFile(e.target.files[0])} />
              <button onClick={handleUpload}>Upload</button>
            </div>

            <h3>Commit Heatmap</h3>
            {renderHeatmap()}
          </div>
        </>
      )}

      {/* ✅ HEATMAP CSS */}
      <style>{`
        .heatmap-grid {
          display: grid;
          grid-template-columns: repeat(53, 12px);
          gap: 4px;
          justify-content: center;
          margin-top: 15px;
        }
        .heat-box {
          width: 12px;
          height: 12px;
          border-radius: 2px;
          background: #1f2933;
        }

        .level-0 { background: #e5e7eb; }
        .level-1 { background: #bbf7d0; }
        .level-2 { background: #4ade80; }
        .level-3 { background: #16a34a; }
        .level-4 { background: #166534; }

      `}</style>
    </div>
  );
}

const styles = {
  container: {
    minHeight: "100vh",
    padding: 20,
    fontFamily: "Arial"
  },
  topBar: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center"
  },
  form: {
    display: "flex",
    gap: 10,
    justifyContent: "center",
    marginTop: 20,
    flexWrap: "wrap"
  },
  heatmapBox: {
    width: "75%",
    margin: "auto",
    marginTop: 30,
    padding: 20,
    borderRadius: 12,
    background: "rgba(255,255,255,0.08)",
    position: "relative"
  },
  topRightUpload: {
    position: "absolute",
    right: 10,
    top: 10,
    display: "flex",
    gap: 6
  }
};

export default App;
